type OAImported0 = abstraction_rights_api::Subject;

// The included crate encodes and checks its own record; its refusal keeps its word.
fn enc_oa_imported0(out: &mut ::std::vec::Vec<u8>, v: &OAImported0, depth: i32) {
    match abstraction_rights_api::internal::encode_subject_at(v, depth) {
        Ok(bytes) => out.extend_from_slice(&bytes),
        Err(e) => ::std::panic::panic_any(Refusal { word: e.word, offset: e.offset }),
    }
}

fn decode_oa_imported0(r: &mut Reader) -> ::std::result::Result<OAImported0, Refusal> {
    match abstraction_rights_api::internal::decode_subject_at(&r.buf[r.pos..], r.depth, r.limit) {
        Ok((v, n)) => {
            r.pos += n;
            Ok(v)
        }
        Err(e) => Err(Refusal { word: e.word, offset: r.pos + e.offset }),
    }
}

fn check_imported_oa_imported0(v: &OAImported0) -> ::std::result::Result<(), Refusal> {
    abstraction_rights_api::internal::check_subject(v, 0, DEPTH_LIMIT).map_err(|e| Refusal { word: e.word, offset: e.offset })
}

fn service_check_oa_imported0(v: &OAImported0) -> ::std::result::Result<(), Refusal> {
    check_imported_oa_imported0(v)
}

fn named_encode_holder(v: &Holder, depth: i32) -> ::std::result::Result<::std::vec::Vec<u8>, Refusal> {
    match ::std::panic::catch_unwind(::std::panic::AssertUnwindSafe(|| {
        let mut out = ::std::vec::Vec::new();
        enc_holder(&mut out, v, depth);
        out
    })) {
        Ok(out) => Ok(out),
        Err(p) => match p.downcast::<Refusal>() {
            Ok(e) => Err(*e),
            Err(p) => ::std::panic::resume_unwind(p),
        },
    }
}

fn decode_holder_at(data: &[u8], depth: i32, limit: i32) -> ::std::result::Result<(Holder, usize), Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth, limit: if limit < DEPTH_LIMIT { limit } else { DEPTH_LIMIT } };
    if depth < 0 || limit < 1 {
        return r.refuse("depth_exceeded");
    }
    r.skip_ws();
    let v = decode_holder(&mut r)?;
    Ok((v, r.pos))
}

fn check_holder(v: &Holder, depth: i32, limit: i32) -> ::std::result::Result<(), Refusal> {
    if depth < 0 || limit < 1 {
        return Err(Refusal { word: "depth_exceeded", offset: 0 });
    }
    let out = named_encode_holder(v, depth)?;
    decode_holder_at(&out, depth, limit).map(|_| ())
}

fn encode_holder_at(v: &Holder, depth: i32) -> ::std::result::Result<::std::vec::Vec<u8>, Refusal> {
    if !(0..DEPTH_LIMIT).contains(&depth) {
        return Err(Refusal { word: "depth_exceeded", offset: 0 });
    }
    let out = named_encode_holder(v, depth)?;
    decode_holder_at(&out, depth, DEPTH_LIMIT)?;
    Ok(out)
}

